node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const orderId = '#W4705780';
const oldItemId = '9716794911';
const newItemId = '2364909101';
const paymentMethodId = 'paypal_5098475';

// 1. Verify order is still pending
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(orderId);
if (order.status !== 'pending') {
  console.log('ERROR: Order is not pending, status:', order.status);
  process.exit(1);
}

// 2. Get old item details from order_items
const oldItem = db.prepare('SELECT * FROM order_items WHERE order_id = ? AND item_id = ?').get(orderId, oldItemId);
if (!oldItem) {
  console.log('ERROR: Old item not found in order');
  process.exit(1);
}

// 3. Get new variant details
const newVariant = db.prepare('SELECT * FROM rt_variants WHERE item_id = ?').get(newItemId);
if (!newVariant || !newVariant.available) {
  console.log('ERROR: New variant not found or unavailable');
  process.exit(1);
}

// 4. Calculate price difference
const diffPrice = Math.round((newVariant.price - oldItem.unit_price) * 100) / 100;
console.log('Old price:', oldItem.unit_price);
console.log('New price:', newVariant.price);
console.log('Price difference:', diffPrice);

// 5. Begin transaction
const txn = db.transaction(() => {
  // Update order status
  db.prepare('UPDATE orders SET status = ? WHERE order_id = ?')
    .run('pending (item modified)', orderId);

  // Update the order_item: swap item_id, price, options
  db.prepare('UPDATE order_items SET item_id = ?, unit_price = ?, options = ? WHERE oi_id = ?')
    .run(newItemId, newVariant.price, newVariant.options, oldItem.oi_id);

  // Insert the payment/refund record for the price difference
  const txnType = diffPrice > 0 ? 'payment' : 'refund';
  const txnAmount = Math.abs(diffPrice);
  db.prepare('INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES (?, ?, ?, ?)')
    .run(orderId, txnType, txnAmount, paymentMethodId);
});

txn();

// 6. Verify the changes
const updatedOrder = db.prepare('SELECT order_id, status FROM orders WHERE order_id = ?').get(orderId);
const updatedItems = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(orderId);
const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(orderId);

console.log('\\n=== Updated Order ===');
console.log(JSON.stringify(updatedOrder, null, 2));
console.log('\\n=== Updated Items ===');
console.log(JSON.stringify(updatedItems, null, 2));
console.log('\\n=== Payment History ===');
console.log(JSON.stringify(payments, null, 2));
console.log('\\nModification completed successfully!');
"
